use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, BufWriter, Write};
use std::process::ExitCode;

/// Running state of one key's total.
#[derive(Clone, Copy)]
enum Total {
    Sum(i64),
    Overflow,
}

fn main() -> ExitCode {
    let Some(path) = env::args().nth(1) else {
        eprintln!("usage: keyed-totals <file>");
        return ExitCode::from(2);
    };

    let text = match fs::read_to_string(&path) {
        Ok(text) => text,
        Err(err) => {
            eprintln!("keyed-totals: cannot read {path}: {err}");
            return ExitCode::FAILURE;
        }
    };

    match run(&text) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("keyed-totals: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run(text: &str) -> Result<(), String> {
    let mut lines = text.split('\n').map(|line| line.strip_suffix('\r').unwrap_or(line));

    // Section one: records, up to the first empty line.
    let mut totals: HashMap<&str, Total> = HashMap::new();
    for line in lines.by_ref() {
        if line.is_empty() {
            break;
        }
        let (key, value) = line
            .split_once(' ')
            .ok_or_else(|| format!("malformed record: {line:?}"))?;
        let value: i64 = value
            .parse()
            .map_err(|_| format!("malformed value in record: {line:?}"))?;
        let entry = totals.entry(key).or_insert(Total::Sum(0));
        if let Total::Sum(sum) = *entry {
            *entry = match sum.checked_add(value) {
                Some(next) => Total::Sum(next),
                None => Total::Overflow,
            };
        }
    }

    // Section two: one query key per line. Empty lines carry no key and are skipped.
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for key in lines.filter(|line| !line.is_empty()) {
        match totals.get(key) {
            None => writeln!(out, "{key}=absent"),
            Some(Total::Sum(sum)) => writeln!(out, "{key}={sum}"),
            Some(Total::Overflow) => writeln!(out, "{key}=overflow"),
        }
        .map_err(|err| format!("cannot write output: {err}"))?;
    }
    out.flush().map_err(|err| format!("cannot write output: {err}"))
}

